def compute(vars):
    difference = vars["v1"] - vars["v2"]
    return {
        "value": difference,
        "trace": {
            "2008_balance": vars["v1"],
            "2007_balance": vars["v2"],
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
